insert into public.empreendimentos (wp_id, slug, nome, chamada, tagline, titulo_hero, descricao, titulo_lazer, descricao_lazer, titulo_localizacao, texto_localizacao, endereco, estagio, pais, dormitorios, vagas, metragem, previsao_entrega, capa_url, logo_url, perspectiva_url, tour_virtual_url, waze_url, videos, destaque_home, mostrar_no_portfolio, aceita_fgts, publicado, ordem) values (1879, 'eixo-leste', 'Eixo Leste', 'R$226 a 320mil', 'Um condomínio exclusivo, sustentável e bem localizado', 'Viva no Coração do Artur Alvim', 'No coração do novo polo de desenvolvimento do Artur Alvim, o Eixo Leste oferece praticidade, conforto e qualidade de vida. Localizado a poucos passos do metrô Artur Alvim e cercado por mercados, escolas e serviços, o empreendimento reúne conveniência e mobilidade. Com áreas de lazer como academia, salão de festas, salão de jogos e espaço gourmet, além de apartamentos modernos e funcionais, o Eixo Leste é a escolha ideal para quem busca viver bem na Zona Leste.', 'Áreas de Lazer que Valorizam o Seu Tempo', 'O Eixo Leste oferece uma infraestrutura de lazer pensada para transformar sua rotina em experiências prazerosas. A academia equipada garante saúde e disposição no dia a dia. O salão de festas e o espaço gourmet proporcionam encontros memoráveis com familiares e amigos, enquanto o salão de jogos cria um ambiente descontraído para relaxar. A lavanderia coletiva traz ainda mais praticidade, facilitando as tarefas do cotidiano. Cada espaço foi planejado para que você viva com conforto, comodidade e equilíbrio, aproveitando ao máximo o que o empreendimento tem a oferecer.', 'O Endereço Ideal para Sua Nova História', 'Situado a apenas 500 metros do metrô Artur Alvim, o Eixo Leste coloca você no centro da mobilidade da Zona Leste. Cercado por mercados, padarias, escolas e serviços essenciais, o empreendimento garante praticidade no dia a dia. Além disso, a proximidade com o Shopping Itaquera, Arena Corinthians e importantes vias de acesso traz ainda mais conveniência e valorização para o seu investimento.', 'Rua Pedreira de Magalhães,
