insert into public.empreendimentos (wp_id, slug, nome, chamada, tagline, titulo_hero, descricao, titulo_lazer, descricao_lazer, titulo_localizacao, texto_localizacao, endereco, estagio, pais, dormitorios, vagas, metragem, previsao_entrega, capa_url, logo_url, perspectiva_url, tour_virtual_url, waze_url, videos, destaque_home, mostrar_no_portfolio, aceita_fgts, publicado, ordem) values (1938, 'neo-home', 'NEO HOME', null, 'Vida Mais Prática e Dinâmica', 'Seu Passaporte para uma Vida Mais Prática e Dinâmica', 'Mais do que um apartamento, o Neo Home é o seu passaporte para uma vida prática e dinâmica na Zona Leste. Localizado a poucos minutos do metrô Artur Alvim e Itaquera, próximo a shoppings, escolas e ao Teatro Opus, o empreendimento une conveniência, lazer e cultura. Com áreas comuns completas academia, salão de festas, salão de jogos, lavanderia e espaço gourmet  oferece o conforto e a segurança de um lar moderno no centro de tudo', 'Lazer completo para você e sua família.', 'O Eixo Leste foi pensado para oferecer muito mais do que um lar: aqui você encontra espaços que valorizam seu tempo e bem-estar. Com academia equipada para cuidar da saúde, salão de festas e espaço gourmet perfeitos para reunir amigos e família, além do salão de jogos para momentos de descontração, cada ambiente foi planejado para tornar o dia a dia mais leve, prático e prazeroso. A lavanderia coletiva completa essa estrutura, trazendo conveniência e modernidade ao seu estilo de vida.', 'More perto de tudo ', null, 'RUA INES MONTEIRO Nº 368 - ARTHUR ALVIM', 'obras_iniciadas', 'Brasil', '1-2 Dorm', '0-1', '25-45m²', '2028-09-09', 'wp/2025/09/5.2.-Salao-de-festas-scaled.webp', 'wp/2025/09/5-1.webp', 'wp/2025/09/RENDER-03.webp', null, 'https://www.waze.com/pt-BR/live-map/directions/br/sp/r.-ines-monteiro,-368?to=place.Ek9SLiBJbsOqcyBNb250ZWlybywgMzY4IC0gUGFycXVlIEFydHVyIEFsdmltLCBTw6NvIFBhdWxvIC0gU1AsIDAzNTY4LTAzMCwgQnJhemlsIjESLwoUChIJKZIYXi9nzpQRENfMbD-EaoYQ8AIqFAoSCRUe3ggvZ86UERmrXR8yIJDF', 