insert into public.empreendimentos (wp_id, slug, nome, chamada, tagline, titulo_hero, descricao, titulo_lazer, descricao_lazer, titulo_localizacao, texto_localizacao, endereco, estagio, pais, dormitorios, vagas, metragem, previsao_entrega, capa_url, logo_url, perspectiva_url, tour_virtual_url, waze_url, videos, destaque_home, mostrar_no_portfolio, aceita_fgts, publicado, ordem) values (2387, 'villa-parque', 'Villa Parque', 'Um novo conceito de viver: leveza, bem-estar e conveniência.', 'No Villa Parque, você encontra o refúgio ideal para viver com leveza, lazer completo e a tranquilidade de estar a poucos passos do Parque Vila do Rodeio.', 'Viva o equilíbrio perfeito entre conforto e natureza', 'Localizado a apenas 1,3 km do Parque Vila do Rodeio, o Villa Parque é o equilíbrio perfeito entre conforto, lazer e qualidade de vida. Com apartamentos modernos e funcionais, o empreendimento foi pensado para quem deseja viver com praticidade, sem abrir mão da tranquilidade de estar perto da natureza. O projeto conta com lazer completo — piscina, academia, salão de festas, salão de jogos, espaço gourmet e pet place — além de elevadores amplos para 10 pessoas, garantindo mais conforto e acessibilidade no dia a dia.
